/**
 * Mochi2D's own analysis on synthetic audio, generated by the tests: the
 * confusion matrices of the strongest element on male and female vowels,
 * uncalibrated and calibrated; levels and the gate; noise, a tone, stereo
 * mixes and a DC offset; glides and bursts; WAV encodings and rates; the
 * latency of sound files (look-ahead) and of live input; and voice profiles.
 * A small synthetic model carries DeepSeek-chan's mouth parameters, so no
 * model files are needed.
 */
import { describe, expect, it } from "vitest";
import { loadMoc } from "../src/core/moc/model.js";
import { AnimationValues } from "../src/anim/values.js";
import { MotionSyncDriver, type MotionSyncTick } from "../src/anim/motion-sync/driver.js";
import { parseMotionSync, type MotionSyncFile } from "../src/anim/motion-sync/file.js";
import { MotionSyncAudioError, decodeMotionSyncWav } from "../src/anim/motion-sync/wav.js";
import {
  VoiceCalibration,
  neutralVoiceProfile,
  voiceProfileFromJson,
  type VoiceProfile,
} from "../src/anim/motion-sync/analysis.js";
import { VOWEL_FORMANTS, synthesizeVowel } from "../src/anim/motion-sync/voice-synth.js";
import { Synth } from "./support/synth.js";
import {
  BASIC,
  ELEMENTS,
  FEMALE,
  MALE,
  VOWELS,
  burstClip,
  clipped,
  concat,
  dsBasic,
  edited,
  glideClip,
  limit,
  pinkNoise,
  silence,
  toLevel,
  tone,
  vowelClip,
  wavFile,
  whiteNoise,
  type Segment,
  type VoiceSpec,
  type WavEncoding,
} from "./support/motion-sync.js";

/** A model with DeepSeek-chan's mouth parameters (ranges and defaults). */
const MODEL = (() => {
  const s = new Synth(4);
  s.part({ id: "P" });
  s.param("ParamMouthOpenY", 0, 1, 0);
  s.param("ParamMouthForm", -1, 1, 0);
  s.param("MouthFunnel", 0, 1, 0);
  s.param("Mouthpucker", 0, 1, 0);
  s.param("MouthPuckerWiden", -1, 1, 0);
  s.mesh({ id: "M", keyforms: [{ positions: [0, 0, 1, 0, 0, 1] }] });
  return loadMoc(s.build());
})();

const file = (json: unknown): MotionSyncFile => parseMotionSync(JSON.stringify(json), "ms");
/** ds-basic, with the engine's smoothing at its most intense and no file smoothing. */
const brisk = () =>
  edited(dsBasic(), (j) => {
    j.Settings[0].PostProcessing.Smoothing = 1;
    for (const p of j.Settings[0].CubismParameters) p.Smooth = 0;
  });

interface Run {
  ticks: MotionSyncTick[];
  /** ParamMouthOpenY after each frame. */
  open: number[];
  values: AnimationValues;
  driver: MotionSyncDriver;
}

/** Plays `channels` at `rate` through `json`'s first setting at 60 frames a second. */
function play(
  channels: Float32Array[],
  rate: number,
  options: {
    json?: unknown;
    profile?: VoiceProfile | null;
    seconds?: number;
    fileSmoothing?: boolean;
  } = {},
): Run {
  const values = new AnimationValues(MODEL);
  const f = file(options.json ?? dsBasic());
  const driver = new MotionSyncDriver(f, values, {
    profile: options.profile ?? null,
    ...(options.fileSmoothing !== undefined ? { fileSmoothing: options.fileSmoothing } : {}),
  });
  const ticks: MotionSyncTick[] = [];
  driver.onTick((t) => ticks.push(t));
  driver.playSound(f.settings[0]!, { sampleRate: rate, channels });
  const open: number[] = [];
  const frames = Math.ceil((options.seconds ?? channels[0]!.length / rate) * 60);
  const i = values.index("ParamMouthOpenY");
  for (let n = 0; n < frames; n++) {
    driver.frame(1 / 60);
    open.push(values.values[i]!);
  }
  return { ticks, open, values, driver };
}

const strongest = (t: MotionSyncTick) =>
  ELEMENTS.reduce((a, b) => (t.weights[b] > t.weights[a] ? b : a));

/** Per true vowel, how often each element is the strongest, within the vowels' nuclei. */
function confusion(run: Run, segments: Segment[]) {
  const m: Record<string, Record<string, number>> = {};
  let right = 0;
  let total = 0;
  for (const s of segments) {
    const row = Object.fromEntries(ELEMENTS.map((e) => [e, 0]));
    for (const t of run.ticks)
      if (t.time > s.start + 0.1 && t.time < s.end - 0.1) {
        const e = strongest(t);
        row[e]!++;
        total++;
        if (e === s.vowel) right++;
      }
    m[s.vowel] = row;
  }
  return { matrix: m, accuracy: right / total };
}

const describeMatrix = (m: Record<string, Record<string, number>>) =>
  Object.entries(m)
    .map(([v, row]) => `${v}: ${JSON.stringify(row)}`)
    .join("; ");

/** A calibration of `voice` from one second of each vowel, at a slightly different pitch. */
function calibrate(voice: VoiceSpec): VoiceProfile {
  const cal = new VoiceCalibration("test voice");
  for (const v of VOWELS)
    cal.add(
      v,
      [
        synthesizeVowel(VOWEL_FORMANTS[v], 1, 48000, {
          f0: voice.f0 * 1.04,
          formantScale: voice.formantScale,
        }),
      ],
      48000,
    );
  return cal.profile();
}

describe("vowels: the strongest element", () => {
  for (const [name, voice, rate] of [
    ["male, 16 kHz", MALE, 16000],
    ["female, 48 kHz", FEMALE, 48000],
  ] as const) {
    for (const calibrated of [false, true]) {
      it(`${name}, ${calibrated ? "calibrated" : "uncalibrated"}: at least 90 % right`, () => {
        const clip = vowelClip(voice, rate);
        const run = play([clip.samples], rate, { profile: calibrated ? calibrate(voice) : null });
        const { matrix, accuracy } = confusion(run, clip.segments);
        expect(accuracy, describeMatrix(matrix)).toBeGreaterThanOrEqual(0.9);
        for (const v of VOWELS) {
          const row = matrix[v]!;
          const n = Object.values(row).reduce((a, b) => a + b, 0);
          expect(row[v]! / n, `${v}: ${describeMatrix(matrix)}`).toBeGreaterThanOrEqual(0.8);
        }
      });
    }
  }

  it("shapes the mouth by the vowel: A opens it most, I and E smile, U and O frown", () => {
    const clip = vowelClip(MALE, 16000);
    const run = play([clip.samples], 16000);
    const mean = (v: string, id: string) => {
      const s = clip.segments.find((x) => x.vowel === v)!;
      const xs = run.ticks
        .filter((t) => t.time > s.start + 0.3 && t.time < s.end - 0.1)
        .map((t) => t.values[id]!);
      return xs.reduce((a, b) => a + b, 0) / xs.length;
    };
    const open = Object.fromEntries(VOWELS.map((v) => [v, mean(v, "ParamMouthOpenY")]));
    const form = Object.fromEntries(VOWELS.map((v) => [v, mean(v, "ParamMouthForm")]));
    expect(open.A).toBeGreaterThan(Math.max(open.I!, open.U!, open.E!, open.O!));
    expect(form.I).toBeGreaterThan(0.5);
    expect(form.E).toBeGreaterThan(0.3);
    expect(form.U).toBeLessThan(-0.5);
    expect(form.O).toBeLessThan(-0.3);
  });
});

describe("levels and the gate", () => {
  const clip = vowelClip(MALE, 16000);

  it("reads quiet vowels (−40 dBFS) like normal ones: the level is the sound's own", () => {
    const quiet = vowelClip(MALE, 16000, { level: -40 });
    const { matrix, accuracy } = confusion(play([quiet.samples], 16000), quiet.segments);
    expect(accuracy, describeMatrix(matrix)).toBeGreaterThanOrEqual(0.9);
  });

  it("gates very quiet vowels (−55 dBFS) to silence: the mouth stays closed", () => {
    const run = play([vowelClip(MALE, 16000, { level: -55 }).samples], 16000);
    expect(run.ticks.every((t) => t.silent && t.weights.Silence === 1)).toBe(true);
    expect(run.open.every((v) => v === 0)).toBe(true);
  });

  it("reads loud vowels (−6 dBFS, peaks limited to −1) like normal ones", () => {
    const loud = limit(toLevel(clip.samples, -6), -1, 16000);
    const peak = loud.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
    expect(20 * Math.log10(peak)).toBeLessThanOrEqual(-1 + 1e-6);
    const { matrix, accuracy } = confusion(play([loud], 16000), clip.segments);
    expect(accuracy, describeMatrix(matrix)).toBeGreaterThanOrEqual(0.9);
  });

  it("still opens the mouth for hard-clipped vowels (+6 dB over the loud ones)", () => {
    const hot = clipped(limit(toLevel(clip.samples, -6), -1, 16000), 6);
    const run = play([hot], 16000);
    const inside = run.ticks.filter((t) =>
      clip.segments.some((s) => t.time > s.start + 0.1 && t.time < s.end - 0.1),
    );
    expect(inside.every((t) => t.weights.Silence < 0.1)).toBe(true);
    expect(inside.every((t) => Object.values(t.values).every(Number.isFinite))).toBe(true);
  });

  it("holds the Silence shape through silence and near silence, without jitter", () => {
    for (const samples of [silence(2, 44100), whiteNoise(2, 44100, -60)]) {
      const run = play([samples], 44100);
      expect(run.ticks.length).toBeGreaterThan(100);
      expect(run.ticks.every((t) => t.silent)).toBe(true);
      expect(run.open.every((v) => v === 0)).toBe(true);
    }
  });

  it("removes a DC offset", () => {
    const dc = Float32Array.from(clip.samples, (v) => v + 0.1);
    const { matrix, accuracy } = confusion(play([dc], 16000), clip.segments);
    expect(accuracy, describeMatrix(matrix)).toBeGreaterThanOrEqual(0.9);
  });
});

describe("sounds that are not vowels", () => {
  it("keeps the mouth near closed for white and pink noise: no vowel dominates", () => {
    for (const noise of [whiteNoise(2, 44100, -20), pinkNoise(2, 44100, -20)]) {
      const run = play([noise], 44100);
      const silenceWins = run.ticks.filter((t) => strongest(t) === "Silence").length;
      expect(silenceWins).toBeGreaterThanOrEqual(0.95 * run.ticks.length);
      // By default the file's Smooth is off: a stray tick opens the mouth a little more.
      expect(Math.max(...run.open)).toBeLessThan(0.15);
      // With it, it damps those ticks as well.
      const smoothed = play([noise], 44100, { fileSmoothing: true });
      expect(Math.max(...smoothed.open)).toBeLessThan(0.1);
    }
  });

  it("gives a steady tone a steady shape", () => {
    const run = play([tone(440, 2, 44100, -18)], 44100);
    const later = run.ticks.filter((t) => t.time > 0.2 && t.time < 1.8).map(strongest);
    const most = later.filter((e) => e === later[0]).length;
    expect(most).toBeGreaterThanOrEqual(0.95 * later.length);
  });

  it("reads vowels in noise (20 dB SNR, white or pink) at least 85 % right", () => {
    for (const [voice, rate] of [
      [MALE, 16000],
      [FEMALE, 48000],
    ] as const) {
      const clip = vowelClip(voice, rate);
      const seconds = clip.samples.length / rate;
      for (const noise of [whiteNoise(seconds, rate, -38, 5), pinkNoise(seconds, rate, -38, 6)]) {
        const noisy = Float32Array.from(clip.samples, (v, i) => v + noise[i]!);
        const { matrix, accuracy } = confusion(play([noisy], rate), clip.segments);
        expect(accuracy, describeMatrix(matrix)).toBeGreaterThanOrEqual(0.85);
      }
    }
  });
});

describe("stereo: channels are mixed to mono by averaging", () => {
  const clip = vowelClip(MALE, 44100);
  const mono = play([clip.samples], 44100);

  it("the same in both channels reads as mono", () => {
    const run = play([clip.samples, clip.samples], 44100);
    expect(run.ticks.map(strongest)).toEqual(mono.ticks.map(strongest));
  });

  it("a vowel in the left channel only is half as loud, and reads the same", () => {
    const run = play([clip.samples, new Float32Array(clip.samples.length)], 44100);
    const voiced = run.ticks.filter((t, i) => !t.silent && !mono.ticks[i]!.silent);
    expect(voiced.length).toBeGreaterThan(200);
    const i0 = run.ticks.indexOf(voiced[100]!);
    expect(run.ticks[i0]!.level).toBeCloseTo(mono.ticks[i0]!.level - 20 * Math.log10(2), 1);
    const { accuracy } = confusion(run, clip.segments);
    expect(accuracy).toBeGreaterThanOrEqual(0.9);
  });

  it("antiphase channels cancel to silence", () => {
    const run = play([clip.samples, Float32Array.from(clip.samples, (v) => -v)], 44100);
    expect(run.ticks.every((t) => t.silent)).toBe(true);
  });

  it("A on the left and O on the right blend the two", () => {
    const a = synthesizeVowel(VOWEL_FORMANTS.A, 1.5, 44100, { f0: 120 });
    const o = synthesizeVowel(VOWEL_FORMANTS.O, 1.5, 44100, { f0: 120 });
    const run = play([a, o], 44100);
    const mid = run.ticks.filter((t) => t.time > 0.2 && t.time < 1.3);
    const mean = (e: "A" | "O" | "I" | "U" | "E") =>
      mid.reduce((s, t) => s + t.weights[e], 0) / mid.length;
    expect(mean("A") + mean("O")).toBeGreaterThan(0.8);
    expect(mean("A") + mean("O")).toBeGreaterThan(4 * (mean("I") + mean("U") + mean("E")));
  });
});

describe("movement", () => {
  it("follows glides A → I → U → E → O → A in order", () => {
    const run = play([glideClip(MALE, 3.5, 44100)], 44100);
    const seq: string[] = [];
    for (const t of run.ticks) {
      const e = strongest(t);
      if (e !== "Silence" && e !== seq[seq.length - 1]) seq.push(e);
    }
    // Every vowel shows, in order (a passing vowel in between is allowed).
    let k = 0;
    for (const e of seq) if (e === "AIUEOA"[k]) k++;
    expect(k, seq.join(" ")).toBe(6);
  });

  it("opens for each 100 ms burst and closes between them", () => {
    const bursts = burstClip(44100);
    const run = play([bursts], 44100, { json: brisk() });
    for (let b = 1; b < 19; b++) {
      const on = run.open.slice(Math.round(b * 0.2 * 60) + 2, Math.round(b * 0.2 * 60) + 6);
      const off = run.open.slice(
        Math.round((b * 0.2 + 0.1) * 60) + 2,
        Math.round((b * 0.2 + 0.2) * 60),
      );
      expect(Math.max(...on), `burst ${b}`).toBeGreaterThan(0.7);
      expect(Math.min(...off), `gap ${b}`).toBeLessThan(0.3);
    }
  });

  it("smoothing (1 to 100) slows the attack", () => {
    const a = concat(silence(0.3, 16000), synthesizeVowel(VOWEL_FORMANTS.A, 1, 16000, { f0: 120 }));
    const rise = (smoothing: number) => {
      const json = edited(brisk(), (j) => (j.Settings[0].PostProcessing.Smoothing = smoothing));
      const run = play([a], 16000, { json });
      return run.open.findIndex((v) => v > 0.45) / 60 - 0.3;
    };
    const fast = rise(1);
    const slow = rise(100);
    expect(fast).toBeLessThan(0.06);
    expect(slow).toBeGreaterThan(fast + 0.15);
  });
});

describe("latency", () => {
  const onset = 0.5;
  const a = concat(silence(onset, 48000), synthesizeVowel(VOWEL_FORMANTS.A, 1, 48000, { f0: 120 }));

  it("sound files: the mouth starts moving within a frame of the sound (look-ahead)", () => {
    const run = play([a], 48000, { json: brisk() });
    const first = run.open.findIndex((v) => v > 0.05);
    // Frame n shows the mouth at time (n + 1)/60.
    expect(Math.abs((first + 1) / 60 - onset)).toBeLessThanOrEqual(1 / 60 + 1e-9);
  });

  it("live input: the mouth moves less than 50 ms after the sound", () => {
    const values = new AnimationValues(MODEL);
    const f = file(brisk());
    const driver = new MotionSyncDriver(f, values);
    // The input hands over what was captured since the previous frame, in 128-sample blocks.
    let read = 0;
    let now = 0;
    driver.setInput(f.settings[0]!, {
      sampleRate: 48000,
      read() {
        const upTo = Math.floor((now * 48000) / 128) * 128;
        const out = a.subarray(read, Math.min(a.length, upTo));
        read = Math.min(a.length, upTo);
        return out;
      },
    });
    const i = values.index("ParamMouthOpenY");
    let moved = -1;
    for (let n = 1; n <= 90 && moved < 0; n++) {
      now = n / 60;
      driver.frame(1 / 60);
      if (values.values[i]! > 0.05) moved = now;
    }
    expect(moved).toBeGreaterThan(onset);
    expect(moved - onset).toBeLessThan(0.05);
  });

  it("live input at the analysis rate, and silence afterwards, settle the mouth", () => {
    const values = new AnimationValues(MODEL);
    const f = file(dsBasic());
    const driver = new MotionSyncDriver(f, values);
    const clip = vowelClip(MALE, 16000, { vowels: ["A"] });
    let pos = 0;
    driver.setInput(f.settings[0]!, {
      sampleRate: 16000,
      read() {
        const out = clip.samples.subarray(pos, Math.min(clip.samples.length, pos + 267));
        pos += out.length;
        return out.length ? out : new Float32Array(267);
      },
    });
    const i = values.index("ParamMouthOpenY");
    let max = 0;
    for (let n = 0; n < 120; n++) {
      driver.frame(1 / 60);
      max = Math.max(max, values.values[i]!);
    }
    expect(max).toBeGreaterThan(0.5);
    expect(driver.tick!.source).toBe("live");
    driver.stop();
    for (let n = 0; n < 40 && driver.setting; n++) driver.frame(1 / 60);
    expect(driver.setting).toBeNull();
  });
});

describe("WAV files", () => {
  const rate = 22050;
  const clip = vowelClip(MALE, rate, { vowels: ["A", "O"] }).samples;

  it("decodes PCM 8, 16, 24 and 32 bits and float 32 and 64 bits, also extensible", () => {
    const steps: Record<WavEncoding, number> = {
      pcm8: 1 / 127,
      pcm16: 1 / 32767,
      pcm24: 1 / 8388607,
      pcm32: 1 / 2147483647,
      float32: 0,
      float64: 0,
    };
    for (const enc of Object.keys(steps) as WavEncoding[])
      for (const extensible of [false, true]) {
        const s = decodeMotionSyncWav(
          wavFile([clip, clip.map((v) => -v)], rate, enc, { extensible }),
        );
        expect(s.sampleRate).toBe(rate);
        expect(s.channels).toHaveLength(2);
        let worst = 0;
        for (let i = 0; i < clip.length; i++)
          worst = Math.max(worst, Math.abs(s.channels[0]![i]! - clip[i]!));
        expect(worst, enc).toBeLessThanOrEqual(steps[enc] + 1e-7);
        expect(s.channels[1]![100]).toBeCloseTo(-s.channels[0]![100]!, 2);
      }
  });

  it("reads every rate from 8 to 192 kHz", () => {
    for (const r of [8000, 16000, 22050, 44100, 48000, 96000, 192000]) {
      const s = decodeMotionSyncWav(wavFile([silence(0.1, r)], r));
      expect(s.sampleRate).toBe(r);
      expect(s.channels[0]!.length).toBe(Math.round(0.1 * r));
    }
  });

  it("refuses what it cannot read, with a MotionSyncAudioError", () => {
    const good = wavFile([silence(0.1, 8000)], 8000);
    expect(() => decodeMotionSyncWav(new Uint8Array(10))).toThrow(MotionSyncAudioError);
    const adpcm = good.slice();
    new DataView(adpcm.buffer).setUint16(20, 2, true);
    expect(() => decodeMotionSyncWav(adpcm)).toThrow(/format 2/);
    const noData = good.slice(0, 36);
    new DataView(noData.buffer).setUint32(4, 28, true);
    expect(() => decodeMotionSyncWav(noData)).toThrow(/no data chunk/);
  });
});

describe("voice profiles", () => {
  it("save and load as JSON; anything else is refused", () => {
    const p = calibrate(MALE);
    expect(Object.keys(p.templates).sort()).toEqual([...VOWELS].sort());
    expect(p.voicedLevel).toBeCloseTo(-18, 0);
    expect(p.floorLevel).toBeNull();
    expect(voiceProfileFromJson(JSON.parse(JSON.stringify(p)))).toEqual(p);
    expect(() => voiceProfileFromJson({ format: "other" })).toThrow(TypeError);
    expect(() => voiceProfileFromJson({ ...p, templates: { A: [[1, 2, 3]] } })).toThrow(
      /templates.A/,
    );
    expect(() => voiceProfileFromJson({ ...p, voicedLevel: "loud" })).toThrow(/voicedLevel/);
  });

  it("a recorded noise floor raises the gate above it", () => {
    const cal = new VoiceCalibration();
    for (const v of VOWELS)
      cal.add(v, [synthesizeVowel(VOWEL_FORMANTS[v], 1, 16000, { f0: 130 })], 16000);
    expect(cal.add("Silence", [whiteNoise(1, 16000, -46)], 16000)).toBeGreaterThan(90);
    const p = cal.profile();
    expect(p.floorLevel!).toBeCloseTo(-46, 0);
    const values = new AnimationValues(MODEL);
    const f = file(dsBasic());
    const d = new MotionSyncDriver(f, values, { profile: p });
    d.playSound(f.settings[0]!, { sampleRate: 16000, channels: [whiteNoise(1, 16000, -44)] });
    let silent = 0;
    d.onTick((t) => (t.silent ? silent++ : 0));
    for (let n = 0; n < 60; n++) d.frame(1 / 60);
    expect(silent).toBe(60);
  });

  it("the neutral profile covers four voice sizes", () => {
    const p = neutralVoiceProfile();
    for (const v of VOWELS) expect(p.templates[v]).toHaveLength(4);
    expect(p.voicedLevel).toBe(-26);
  });
});

describe("what a tick reports", () => {
  it("the weights sum to 1, with the level, the values and the time", () => {
    const clip = vowelClip(MALE, 16000, { vowels: ["A"] });
    const run = play([clip.samples], 16000);
    expect(run.ticks.length).toBeGreaterThan(70);
    for (const t of run.ticks) {
      const sum = ELEMENTS.reduce((s, e) => s + t.weights[e], 0);
      expect(sum).toBeCloseTo(1, 12);
      expect(Object.keys(t.values)).toEqual(BASIC.params.map((p) => p.id));
      expect(t.setting).toEqual({ name: "Mouth basic", id: "MS_Basic" });
      expect(t.source).toBe("sound");
    }
    const mid = run.ticks.find((t) => t.time > 0.8)!;
    expect(mid.level).toBeCloseTo(-18, 0);
    expect(mid.silent).toBe(false);
  });
});
